Function palabra <- ComoLeFue(codigo As Integer)
  Define palabra As String;
  If codigo = 200 Then
    palabra <- "bien";
  Else
    palabra <- "problema";
  EndIf
EndFunction

Algorithm Estado
  Define codigo As Integer;
  Read codigo;
  Write ComoLeFue(codigo);
EndAlgorithm

